}

private final class AtomicCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var storedValue = 0

    @discardableResult
    func increment() -> Int {
        lock.lock()
        storedValue += 1
        let value = storedValue
        lock.unlock()
        return value
    }

    @discardableResult
    func decrement() -> Int {
        lock.lock()
        storedValue -= 1
        let value = storedValue
        lock.unlock()
        return value
    }

    var value: Int {
        lock.lock()
        defer { lock.unlock() }
        return storedValue
    }
}

private final class AtomicMax: @unchecked Sendable {
    private let lock = NSLock()
    private var storedValue = 0

    func record(_ value: Int) {
        lock.lock()
        storedValue = max(storedValue, value)
        lock.unlock()
    }

    var value: Int {
        lock.lock()
        defer { lock.unlock() }
        return storedValue
    }
}

