                ),
                systemMessage(
                    "member-left",
                    systemType: "member_left",
                    text: "Member left",
                    subject: carol,
                    recordedAt: 1_700_000_002
                ),
                systemMessage(
                    "admin-added",
                    systemType: "admin_added",
                    text: "Admin added",
                    actor: alice,
                    subject: bob,
                    recordedAt: 1_700_000_003
                ),
                systemMessage(
                    "admin-added-self-without-actor",
