        await Self.settlePendingOutgoingMediaSends(state)

        #expect(state.pendingMediaAttachments.isEmpty)
        #expect(state.draftText.isEmpty)
        #expect(state.selectedPendingOutgoingMediaMessages.isEmpty)
    }

