@MainActor
private func waitFor(attempts: Int = 100, _ predicate: @MainActor () -> Bool) async -> Bool {
    for _ in 0..<attempts {
        if predicate() { return true }
        try? await Task.sleep(nanoseconds: 10_000_000)
    }
    return predicate()
}

